{
  "item_id": "PRISMA_2020_1",
  "elements": [
    {
      "element_id": "prisma_2020_1_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "The impact of selection criteria and study design on reported survival outcomes in extracorporeal oxygenation cardiopulmonary resuscitation (ECPR): a systematic review and meta-analysis",
      "reason": "The title explicitly identifies the report as 'a systematic review and meta-analysis', fulfilling the requirement to label the report as a systematic review."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "The impact of selection criteria and study design on reported survival outcomes in extracorporeal oxygenation cardiopulmonary resuscitation (ECPR)",
      "reason": "The title states the main objective/review question: the impact of selection criteria and study design on survival outcomes in the ECPR population, conveying the key topic and focus of the review."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "a systematic review and meta-analysis",
      "reason": "The title includes supplementary information about the analysis method, indicating that a meta-analysis was performed in addition to the systematic review."
    }
  ],
  "confidence": 96
}

{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Extracorporeal membrane oxygenation (ECMO) for refractory cardiac arrest (RCA, ECPR) provides adequate systemic perfusion while the underlying cause may be diagnosed and treated. Whilst promising outcomes have been reported [1-3], survival rates vary widely [3] which is likely due to differences in study design, geographical",
      "reason": "The Background describes the current state of knowledge (ECPR provides systemic perfusion with promising reported outcomes) and the key uncertainty (survival rates vary widely, likely due to differences in study design and geography), which is corroborated by the abstract's statement that outcomes 'vary considerably due to differing study designs and selection criteria.'"
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "However, reported outcomes vary considerably due to differing study designs and selection criteria. This review assessed the impact of pre-defined selection criteria on ECPR survival.",
      "reason": "The importance and need for the review are explained: variable ECPR outcomes linked to differing designs and selection criteria motivate the review, and the conclusion reinforces the need by noting that 'Well-designed prospective studies... are required to ensure appropriate application of what is a costly intervention.'"
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence contains no mention of existing similar systematic reviews, no citation of a previous review, and no explanation of the current review's relationship to prior reviews; the retrieved portion of the Background only cites outcome studies [1-3]."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Extracorporeal membrane oxygenation (ECMO) for refractory cardiac arrest (RCA, ECPR) provides adequate systemic perfusion while the underlying cause may be diagnosed and treated.",
      "reason": "This is a review of survival outcomes of ECPR (an intervention), and the Background briefly describes the proposed mechanism of action: extracorporeal perfusion support maintaining circulation while the underlying cause of the arrest is diagnosed and treated."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review examines the association of selection criteria and study design with reported survival outcomes rather than evaluating a complex multi-component intervention or delivery context; no retrieved evidence indicates a logic model was considered or needed."
    }
  ],
  "confidence": 78
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "Randomised trials, non-randomised controlled trials, and observational studies (cohort studies and casecontrol studies) were included. The population included adults (age above 12) with IHCA or OHCA of any origin.",
      "reason": "The Eligibility Criteria section fully specifies study characteristics: a PICO framework (adults with cardiac arrest in any setting OHCA/IHCA qualifying for ECPR; ECPR vs manual/mechanical CPR; favourable neurological status or survival at study end), eligible designs (RCTs, non-randomised controlled trials, observational cohort and case-control studies), setting, age threshold (>12), minimum ECPR patient number (>5), and outcome/follow-up definitions (neurological outcome at discharge using study-specified definitions; survival to end of each study period)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "Contemporary studies from January 2000 to June 2021 were included. Only English language studies were included.",
      "reason": "Report characteristics are specified: dissemination window (January 2000 to June 2021), language restriction (English only), and publication status (abstracts, editorials, comments, letters, case reports, and reviews were excluded, implying full journal publications only)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The stated exclusion criteria (animal/ecological studies, case reports, reviews, abstracts, editorials, comments, letters, ≤5 ECPR patients, or failure to report ECPR eligibility/timing criteria) contain no outcome-based exclusions; no evidence indicates studies were excluded because outcomes were unmeasured or unreported, so this distinction requirement does not apply."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "Results are reported separately for pre-defined subgroups based on type of study (retrospective or prospective), and the location of cardiac arrest (IHCA vs OHCA).",
      "reason": "The synthesis groups (prospective vs retrospective design; OHCA vs IHCA; meta-regression by number of inclusion criteria, arrest-to-ECMO time, year, and study type) directly correspond to the review objectives stated in text_5: analysing survival in studies with defined inclusion criteria for OHCA and IHCA and examining the association of prospective selection criteria and the number of inclusion criteria with survival."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "Notable eligibility restrictions are stated (English language only, date range January 2000 to June 2021, exclusion of studies with ≤5 ECPR patients, age >12) but no rationale for any of these restrictions is provided anywhere in the retrieved evidence."
    }
  ],
  "confidence": 82
}

